{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])
    node_map = {node["id"]: node for node in nodes}
    children = {}
    for node in nodes:
        parent = node.get("parent")
        if parent:
            children.setdefault(parent, []).append(node["id"])
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))
    removed = set()
    removed_order = []
    for node in sorted_nodes:
        nid = node["id"]
        if (node["removable"]
                and node["symbol"] not in required_symbols
                and node["parent"] is not None):
            child_ids = children.get(nid, [])
            if all(cid in removed for cid in child_ids):
                removed.add(nid)
                removed_order.append(nid)
    retained_ids = sorted([node["id"] for node in nodes if node["id"] not in removed])
    return {"removed_node_ids": removed_order, "retained_node_ids": retained_ids}"}
